Below is a simple Qt5 (C++) example that provides a GUI to pick a directory, scans that directory for Excel files (.xls, .xlsx) and converts each to CSV placing the CSVs in a new folder inside the chosen directory.

Important notes up front:
- This approach uses ActiveX/COM (QAxObject) to drive Microsoft Excel, so it works only on Windows and requires Excel to be installed.
- Build with Qt's AxContainer module (add axcontainer to QT in the .pro).
- Make sure your Qt build (32/64-bit) matches the installed Office bitness.

Project file (example .pro):
----------------------------
QT += widgets axcontainer
CONFIG += c++11
SOURCES += main.cpp

Single-file example (main.cpp):
-------------------------------
#include <QApplication>
#include <QWidget>
#include <QPushButton>
#include <QVBoxLayout>
#include <QFileDialog>
#include <QTextEdit>
#include <QDir>
#include <QFileInfoList>
#include <QFileInfo>
#include <QMessageBox>
#include <QDateTime>
#include <QDebug>
#include <QAxObject>

static void logMessage(QTextEdit* log, const QString& msg) {
    if (!log) return;
    log->append(QDateTime::currentDateTime().toString("[yyyy-MM-dd hh:mm:ss] ") + msg);
    QApplication::processEvents();
}

bool convertExcelToCsv(const QString& excelPath, const QString& csvPath, QTextEdit* log) {
    // Use Excel COM to open workbook and SaveAs csv
    // This will overwrite csvPath if exists.
    logMessage(log, QString("Converting: %1 -> %2").arg(excelPath, csvPath));

    QAxObject excel("Excel.Application");
    if (excel.isNull()) {
        logMessage(log, "Failed to create Excel COM object. Is Excel installed?");
        return false;
    }

    // Make Excel invisible
    excel.setProperty("Visible", false);
    excel.setProperty("DisplayAlerts", false);

    QAxObject* workbooks = excel.querySubObject("Workbooks");
    if (!workbooks) {
        logMessage(log, "Failed to get Workbooks object.");
        excel.dynamicCall("Quit()");
        return false;
    }

    // Open workbook (read-only)
    QVariant vwb = workbooks->querySubObject("Open(const QString&)", excelPath)->dynamicCall("GetType()");
    // Instead directly use Open and capture pointer:
    QAxObject* workbook = workbooks->querySubObject("Open(const QString&)", excelPath);
    if (!workbook) {
        logMessage(log, QString("Failed to open workbook: %1").arg(excelPath));
        excel.dynamicCall("Quit()");
        return false;
    }

    // Excel SaveAs CSVFileFormat = 6 (xlCSV)
    // For .xlsx content with multiple sheets, SaveAs with file format 6 saves the active sheet as CSV.
    // If you want each sheet separately, you'd need to iterate sheets. Here we save the first/active sheet.
    const int xlCSV = 6;
    // Some versions may need local parameter; provide arguments as QVariantList for optional parameters.
    QVariant returned = workbook->dynamicCall("SaveAs(const QString&, int)", csvPath, xlCSV);
    Q_UNUSED(returned);

    // Close workbook without saving changes
    workbook->dynamicCall("Close(bool)", false);
    delete workbook;
    delete workbooks;

    excel.dynamicCall("Quit()");
    return true;
}

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    QWidget window;
    window.setWindowTitle("Excel -> CSV Batch Converter");
    window.resize(600, 400);

    QVBoxLayout* layout = new QVBoxLayout(&window);

    QPushButton* btnSelect = new QPushButton("Select Directory");
    layout->addWidget(btnSelect);

    QTextEdit* log = new QTextEdit();
    log->setReadOnly(true);
    layout->addWidget(log);

    QObject::connect(btnSelect, &QPushButton::clicked, [&]() {
        QString dir = QFileDialog::getExistingDirectory(&window, "Select Directory", QString(),
                                                        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);
        if (dir.isEmpty()) return;

        logMessage(log, QString("Selected directory: %1").arg(dir));

        QDir inputDir(dir);
        // Create output folder
        QString outFolderName = "csv_output";
        QString outPath = inputDir.filePath(outFolderName);
        QDir().mkpath(outPath);
        logMessage(log, QString("Output folder: %1").arg(outPath));

        // Find .xls and .xlsx files (non-recursive). If you want recursive, use QDirIterator.
        QStringList nameFilters;
        nameFilters << "*.xls" << "*.xlsx";
        QFileInfoList files = inputDir.entryInfoList(nameFilters, QDir::Files | QDir::NoSymLinks);

        if (files.isEmpty()) {
            logMessage(log, "No Excel files found in selected directory.");
            return;
        }

        int success = 0;
        int fail = 0;

        for (const QFileInfo& fi : files) {
            QString excelFilePath = fi.absoluteFilePath();
            QString baseName = fi.completeBaseName(); // for .xls.gz etc this may differ; completeBaseName is fine.
            // If file name contains multiple dots (like name.part.xlsx), completeBaseName returns everything up to last dot.
            QString csvFilePath = QDir(outPath).filePath(baseName + ".csv");

            bool ok = false;
            // Attempt conversion; wrap in try/catch-like behavior: QAxObject returns errors via COM exceptions; but here we check returned objects.
            try {
                ok = convertExcelToCsv(excelFilePath, csvFilePath, log);
            } catch (...) {
                ok = false;
            }

            if (ok) {
                logMessage(log, QString("Saved CSV: %1").arg(csvFilePath));
                ++success;
            } else {
                logMessage(log, QString("Failed to convert: %1").arg(excelFilePath));
                ++fail;
            }
        }

        logMessage(log, QString("Done. Success: %1  Fail: %2").arg(success).arg(fail));
        QMessageBox::information(&window, "Conversion complete",
                                 QString("Finished converting %1 Excel files.\nSuccess: %2\nFail: %3")
                                 .arg(files.count()).arg(success).arg(fail));
    });

    window.show();
    return app.exec();
}

Notes and suggestions:
- This implementation saves the active sheet of each workbook to a single CSV file named after the workbook. If you want to export every sheet as a separate CSV file, iterate workbook->querySubObject("Worksheets") and save each Worksheet by selecting it and calling SaveAs with a distinct name.
- If you need cross-platform conversion (Linux/macOS) or to avoid requiring Excel, consider using a library that can read .xlsx/.xls files (e.g., libxlsxwriter is for writing only; alternatives include OpenXLSX, xlnt, or calling a command-line tool like LibreOffice in headless mode to convert files).
- If you expect many or large files, you may want to run conversions on a background thread and update the UI via signals/slots to avoid UI blocking.

That should get you started. If you want a version that exports each worksheet separately, or a cross-platform solution (using LibreOffice headless or a library), tell me and I can provide that.

